import { useState, useRef, useCallback } from "react";

// ─── HELPERS ─────────────────────────────────────────────────────────────────

const fmt = (n) => new Intl.NumberFormat("es-AR", { maximumFractionDigits: 2 }).format(n);
const mdRender = (t) =>
  (t || "")
    .replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>")
    .replace(/\*(.*?)\*/g, "<em>$1</em>")
    .replace(/^- (.+)/gm, "<span style='display:block;padding-left:12px'>· $1</span>")
    .replace(/\n/g, "<br/>");

// ─── PROMPTS ─────────────────────────────────────────────────────────────────

const AUDIT_PROMPT = (fileName) => `
Sos un arquitecto senior especialista en documentación técnica y cómputo métrico. Analizás el plano/documento: "${fileName}".

Realizá DOS tareas y devolvé ÚNICAMENTE un JSON válido (sin markdown, sin texto extra):

{
  "proyecto": "nombre inferido",
  "estado_documentacion": "completa" | "incompleta" | "parcial",
  "puntaje_completitud": 0-100,
  "sectores": [
    {
      "nombre": "Planta Baja",
      "superficie_m2": 85,
      "items": [
        { "categoria": "Estructura", "material": "Hormigón H-21", "cantidad": 18.5, "unidad": "m³", "detalle": "Losa de fundación", "confianza": "alta" }
      ]
    }
  ],
  "resumen_general": [
    { "material": "Cemento Portland", "cantidad_total": 102, "unidad": "bolsas 50kg", "sectores_involucrados": ["Fundaciones", "Planta Baja"] }
  ],
  "faltantes": [
    {
      "id": "F001",
      "sector": "Planta Baja",
      "categoria": "Pisos",
      "descripcion": "No se especifica tipo ni medidas de revestimiento de piso en estar-comedor",
      "impacto": "crítico" | "importante" | "menor",
      "datos_necesarios": "Tipo de material (porcellanato/cerámico/madera), medida de placa, junta, y superficie exacta en m²",
      "bloquea_computo": true
    }
  ],
  "advertencias": [
    {
      "id": "A001",
      "descripcion": "Medidas de fachada norte no coinciden con planta baja (diferencia de 0.30m)",
      "sector": "Fachada",
      "tipo": "inconsistencia" | "dato_estimado" | "especificacion_incompleta"
    }
  ]
}

Para los FALTANTES, buscá activamente:
- Pisos sin tipo de material ni m² definidos
- Revestimientos sin especificación (baños, cocina)
- Muros sin definición de mampostería
- Aberturas (puertas/ventanas) sin medidas ni materiales
- Instalaciones sin especificación (eléctrica, sanitaria, gas)
- Cubierta sin tipo ni materialidad
- Fundaciones sin cota ni especificación estructural
- Losas sin espesor ni armadura
- Revoques sin especificación (tipo, capas)
- Cualquier superficie sin medida acotada

El campo "confianza" en items: "alta" = dato explícito en plano, "media" = inferido, "baja" = estimado.
Sé exhaustivo. Un faltante puede costar semanas de obra parada.
`;

const CHAT_PROMPT = (projectName, computo, faltantes, advertencias) => `
Sos BELFAST, asistente técnico de la plataforma de obra para el proyecto "${projectName}".

CÓMPUTO MÉTRICO DISPONIBLE:
${JSON.stringify(computo?.sectores || [], null, 2)}

RESUMEN GENERAL:
${JSON.stringify(computo?.resumen_general || [], null, 2)}

INFORMACIÓN FALTANTE EN EL PROYECTO (${(faltantes||[]).length} items):
${JSON.stringify(faltantes || [], null, 2)}

ADVERTENCIAS Y OBSERVACIONES (${(advertencias||[]).length} items):
${JSON.stringify(advertencias || [], null, 2)}

REGLAS CRÍTICAS:
1. Si te preguntan algo que SÍ está en el cómputo → respondé con el dato exacto, cantidad y unidad. Sé directo como un maestro mayor de obras.
2. Si te preguntan algo que NO está en el cómputo porque FALTA información del plano → NO inventes cantidades. Respondé exactamente así:
   "⚠️ **DATO FALTANTE** — [descripción del faltante]. El estudio ya fue notificado automáticamente. Se requiere: [datos_necesarios del faltante]."
3. Si el dato fue ESTIMADO (confianza baja) → avisá que es estimación y recomendá confirmar con el estudio.
4. Siempre en español rioplatense, tono directo y práctico.
5. Usá **negritas** para cantidades y materiales.
6. Máximo 200 palabras.
`;

