// ─── MAIN ─────────────────────────────────────────────────────────────────────

export default function App() {
  const [role, setRole] = useState(null);
  const [apiKey, setApiKey] = useState(() => localStorage.getItem("belfast_key") || "");
  const [apiKeyInput, setApiKeyInput] = useState("");

  const [projectName, setProjectName] = useState(DEMO_DATA.proyecto);
  const [computo, setComputo] = useState(DEMO_DATA);
  const [pdfStatus, setPdfStatus] = useState("demo");
  const [pdfName, setPdfName] = useState(null);

  const [messages, setMessages] = useState([]);
  const [alerts, setAlerts] = useState([]); // Alerts sent to studio
  const [input, setInput] = useState("");
  const [isTyping, setIsTyping] = useState(false);
  const [aiError, setAiError] = useState(null);
  const [view, setView] = useState("chat");
  const [activeAuditTab, setActiveAuditTab] = useState("faltantes");

  const chatEndRef = useRef(null);
  const fileRef = useRef(null);

  const faltantes = computo?.faltantes || [];
  const advertencias = computo?.advertencias || [];
  const criticos = faltantes.filter(f => f.impacto === "crítico");
  const puntaje = computo?.puntaje_completitud ?? 62;

  const startChat = useCallback((r, data) => {
    const name = data?.proyecto || projectName;
    const f = data?.faltantes || [];
    const criticos = f.filter(x => x.impacto === "crítico").length;
    setMessages([{
      role: "ai",
      text: r === "constructor"
        ? `Hola. Soy **BELFAST**, tu asistente técnico para **${name}**.\n\nTengo el cómputo cargado. ${f.length > 0 ? `⚠️ Hay **${f.length} items faltantes** en la documentación (${criticos} críticos) — si me preguntás algo que no está definido, te aviso y el estudio recibe una alerta automática.\n\n` : ""}¿Qué necesitás saber?`
        : `Bienvenido al panel del estudio.\n\nProyecto: **${name}**. Documentación al **${data?.puntaje_completitud ?? 62}%** de completitud.\n\n${f.length > 0 ? `⚠️ Se detectaron **${f.length} items faltantes** — revisalos en la solapa **Auditoría** para completar la documentación antes del inicio de obra.` : "✓ Documentación completa."}`,
    }]);
  }, [projectName]);

  const handleRoleSelect = (r) => {
    setRole(r);
    startChat(r, computo);
    setView("chat");
  };

  // ── PDF UPLOAD ──
  const handlePdf = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!apiKey) { alert("Configurá tu API Key primero."); return; }

    setPdfName(file.name);
    setPdfStatus("analyzing");
    setView("chat");
    setMessages([{ role: "ai", text: `Analizando **${file.name}**...\n\nEstoy leyendo el plano, extrayendo el cómputo métrico e identificando toda la documentación faltante. Esto puede tomar un minuto.` }]);

    try {
      const base64 = await new Promise((res, rej) => {
        const r = new FileReader();
        r.onload = () => res(r.result.split(",")[1]);
        r.onerror = rej;
        r.readAsDataURL(file);
      });

      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-api-key": apiKey, "anthropic-version": "2023-06-01", "anthropic-dangerous-direct-browser-access": "true" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 4000,
          messages: [{ role: "user", content: [
            { type: "document", source: { type: "base64", media_type: "application/pdf", data: base64 } },
            { type: "text", text: AUDIT_PROMPT(file.name) },
          ]}],
        }),
      });

      const data = await res.json();
      if (data.error) throw new Error(data.error.message);
      const raw = data.content?.map(b => b.text || "").join("").replace(/```json|```/g, "").trim();
      const parsed = JSON.parse(raw);

      setComputo(parsed);
      setProjectName(parsed.proyecto || file.name.replace(".pdf", ""));
      setPdfStatus("ready");

      const f = parsed.faltantes || [];
      const crit = f.filter(x => x.impacto === "crítico").length;

      setMessages([{ role: "ai",
        text: `✅ **Análisis completado** — ${file.name}\n\n**Documentación:** ${parsed.puntaje_completitud}% completa\n**Sectores procesados:** ${parsed.sectores?.length || 0}\n**Items faltantes:** ${f.length} (${crit} críticos)\n\n${crit > 0 ? `⚠️ Hay **${crit} items críticos** que bloquean el cómputo. El estudio debe completar esta información antes del inicio de obra.\n\n` : ""}Podés ver el detalle completo en la solapa **Auditoría**, o preguntame lo que necesites.`,
      }]);
    } catch (err) {
      setPdfStatus("error");
      setMessages([{ role: "ai", text: `Error analizando el PDF: ${err.message}\n\nVerificá que sea un plano legible e intentá de nuevo.` }]);
    }
  };

  // ── CHAT ──
  const sendMessage = async (text) => {
    const msg = (text || input).trim();
    if (!msg) return;
    setInput("");
    setAiError(null);
    const userMsg = { role: "user", text: msg };
    setMessages(prev => [...prev, userMsg]);
    setIsTyping(true);

    if (!apiKey) {
      setTimeout(() => {
        setMessages(prev => [...prev, { role: "ai", text: "Para activar la IA configurá tu **API Key de Anthropic** en la pantalla de inicio." }]);
        setIsTyping(false);
      }, 400);
      return;
    }

    try {
      const history = [...messages, userMsg].map(m => ({ role: m.role === "ai" ? "assistant" : "user", content: m.text }));
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-api-key": apiKey, "anthropic-version": "2023-06-01", "anthropic-dangerous-direct-browser-access": "true" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 1000,
          system: CHAT_PROMPT(projectName, computo, faltantes, advertencias),
          messages: history,
        }),
      });
      const data = await res.json();
      if (data.error) throw new Error(data.error.message);
      const reply = data.content?.map(b => b.text || "").join("") || "";

      // If reply contains DATO FALTANTE, create an alert to studio
      if (reply.includes("DATO FALTANTE")) {
        const newAlert = {
          id: Date.now(),
          from: "constructor",
          query: msg,
          time: new Date().toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit" }),
          date: new Date().toLocaleDateString("es-AR"),
          read: false,
        };
        setAlerts(prev => [newAlert, ...prev]);
      }

      setMessages(prev => [...prev, { role: "ai", text: reply }]);
    } catch (err) {
      setAiError("Error al conectar. Verificá tu API key.");
    } finally {
      setIsTyping(false);
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: "smooth" }), 100);
    }
  };

  // ─── LOGIN SCREEN ────────────────────────────────────────────────────────────

  if (!role) return (
    <div style={{ minHeight: "100vh", background: "#f0ece3", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "24px", fontFamily: "'Cormorant Garamond', serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Raleway:wght@300;400;600;700;800&family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;1,400&family=Libre+Baskerville:wght@400;700&family=JetBrains+Mono:wght@300;400;500&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        .bp { position: fixed; inset: 0; background-image: linear-gradient(rgba(160,140,100,0.06) 1px, transparent 1px), linear-gradient(90deg, rgba(160,140,100,0.06) 1px, transparent 1px); background-size: 28px 28px; }
        .rcard { padding: 26px 20px; background: #faf7f0; border: 1px solid #d8d0bc; cursor: pointer; transition: all .2s; }
        .rcard:hover { background: #f4f0e4; border-color: #8b7355; transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,0.07); }
        .ki { width: 100%; padding: 9px 12px; background: #faf7f0; border: 1px solid #d8d0bc; color: #2c2520; font-family: 'JetBrains Mono', monospace; font-size: 12px; outline: none; }
        .ki:focus { border-color: #8b7355; }
        .kb { padding: 9px 16px; background: #2c2520; border: none; color: #f0ece3; font-family: 'JetBrains Mono', monospace; font-size: 9px; letter-spacing: 2px; cursor: pointer; }
      `}</style>
      <div className="bp" />
      <div style={{ position: "relative", width: "100%", maxWidth: "400px" }}>
        <div style={{ textAlign: "center", marginBottom: "36px" }}>
          <img src="data:image/jpeg;base64," alt="Belfast Construction Management" style={{ width: "160px", height: "auto", marginBottom: "8px", display: "block", margin: "0 auto 8px" }} />
          <div style={{ display: "flex", alignItems: "baseline", gap: "0px", justifyContent: "center" }}>
            <span style={{ fontFamily: "'Raleway', sans-serif", fontSize: "32px", fontWeight: 800, color: "#1a1210", letterSpacing: "4px" }}>BELFAST</span><span style={{ fontFamily: "'Raleway', sans-serif", fontSize: "32px", fontWeight: 300, color: "#8b5e2a", letterSpacing: "2px" }}>IA</span>
          </div>
          <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#9a8e7a", letterSpacing: "3px", marginTop: "5px" }}>GESTIÓN COLABORATIVA DE OBRA</div>
        </div>

        {/* API Key */}
        <div style={{ marginBottom: "24px", padding: "14px 16px", background: "#faf7f0", border: "1px solid #d8d0bc" }}>
          <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#9a8e7a", letterSpacing: "2px", textTransform: "uppercase", marginBottom: "8px" }}>
            Anthropic API Key {apiKey && <span style={{ color: "#5a7a4a" }}>✓ configurada</span>}
          </div>
          <div style={{ display: "flex" }}>
            <input className="ki" type="password" placeholder={apiKey ? "••••••••••••" : "sk-ant-api03-..."} value={apiKeyInput} onChange={e => setApiKeyInput(e.target.value)} onKeyDown={e => { if (e.key === "Enter" && apiKeyInput.startsWith("sk-ant-")) { localStorage.setItem("belfast_key", apiKeyInput); setApiKey(apiKeyInput); setApiKeyInput(""); }}} />
            <button className="kb" onClick={() => { if (apiKeyInput.startsWith("sk-ant-")) { localStorage.setItem("belfast_key", apiKeyInput); setApiKey(apiKeyInput); setApiKeyInput(""); }}}>OK</button>
          </div>
          {!apiKey && <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#b0a48e", marginTop: "5px" }}>console.anthropic.com → API Keys (gratis para empezar)</div>}
        </div>

        <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#9a8e7a", letterSpacing: "3px", textAlign: "center", marginBottom: "12px", textTransform: "uppercase" }}>Ingresar como</div>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "10px" }}>
          <div className="rcard" onClick={() => handleRoleSelect("studio")}>
            <svg width="26" height="26" viewBox="0 0 26 26" fill="none" style={{ marginBottom: "10px" }}>
              <polygon points="13,2 24,9 24,17 13,24 2,17 2,9" fill="none" stroke="#4a6a8a" strokeWidth="1.2"/>
              <circle cx="13" cy="13" r="3" fill="none" stroke="#4a6a8a" strokeWidth="1"/>
              <line x1="13" y1="2" x2="13" y2="24" stroke="#4a6a8a" strokeWidth="0.4" strokeDasharray="2,1"/>
              <line x1="2" y1="13" x2="24" y2="13" stroke="#4a6a8a" strokeWidth="0.4" strokeDasharray="2,1"/>
            </svg>
            <div style={{ fontFamily: "'Libre Baskerville', serif", fontSize: "14px", color: "#2c2520", marginBottom: "4px" }}>Estudio</div>
            <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#9a8e7a", lineHeight: 1.5 }}>Subís planos, la IA audita y genera el cómputo</div>
          </div>
          <div className="rcard" onClick={() => handleRoleSelect("constructor")}>
            <svg width="26" height="26" viewBox="0 0 26 26" fill="none" style={{ marginBottom: "10px" }}>
              <rect x="2" y="12" width="22" height="12" fill="none" stroke="#8a5a3a" strokeWidth="1.2"/>
              <polygon points="1,12 13,2 25,12" fill="none" stroke="#8a5a3a" strokeWidth="1.2"/>
              <rect x="9" y="17" width="8" height="7" fill="none" stroke="#8a5a3a" strokeWidth="0.8"/>
            </svg>
            <div style={{ fontFamily: "'Libre Baskerville', serif", fontSize: "14px", color: "#2c2520", marginBottom: "4px" }}>Constructora</div>
            <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#9a8e7a", lineHeight: 1.5 }}>Consultás materiales y cómputo en obra</div>
          </div>
        </div>
        <div style={{ textAlign: "center", marginTop: "16px", fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#c4b89a" }}>
          Demo disponible sin API Key
        </div>
      </div>
    </div>
  );

  // ─── MAIN SHELL ──────────────────────────────────────────────────────────────

  const isConstructor = role === "constructor";
  const accentColor = isConstructor ? "#8a5a3a" : "#4a6a8a";
  const unreadAlerts = alerts.filter(a => !a.read).length;
  const totalPending = faltantes.length;
  const critCount = criticos.length;

  return (
    <div style={{ height: "100vh", display: "flex", flexDirection: "column", background: "#f0ece3", fontFamily: "'Cormorant Garamond', serif", overflow: "hidden" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Raleway:wght@300;400;600;700;800&family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;1,400&family=Libre+Baskerville:wght@400;700&family=JetBrains+Mono:wght@300;400;500&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }
        html, body, #root { height: 100%; overflow: hidden; }
        ::-webkit-scrollbar { width: 3px; }
        ::-webkit-scrollbar-thumb { background: #c4b89a; }
        .bp-bg { position: fixed; inset: 0; z-index: 0; background-image: linear-gradient(rgba(160,140,100,0.055) 1px, transparent 1px), linear-gradient(90deg, rgba(160,140,100,0.055) 1px, transparent 1px); background-size: 28px 28px; pointer-events: none; }
        .msg-in { animation: mi .22s ease; }
        @keyframes mi { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }
        .tdot { display: inline-block; width: 5px; height: 5px; border-radius: 50%; background: #8b7355; margin: 0 2px; animation: td 1.2s ease infinite; }
        .tdot:nth-child(2) { animation-delay: .2s; } .tdot:nth-child(3) { animation-delay: .4s; }
        @keyframes td { 0%,60%,100% { transform: translateY(0); } 30% { transform: translateY(-4px); } }
        .qq { padding: 6px 10px; background: #faf7f0; border: 1px solid #d4ccb8; color: #7a6a58; font-family: 'JetBrains Mono', monospace; font-size: 9px; cursor: pointer; white-space: nowrap; flex-shrink: 0; transition: all .15s; }
        .qq:active, .qq:hover { background: rgba(139,115,85,0.08); border-color: #8b7355; color: #4a3728; }
        .nav-btn { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; padding: 5px 2px; background: transparent; border: none; cursor: pointer; color: #b0a48e; font-family: 'JetBrains Mono', monospace; font-size: 7px; letter-spacing: 0.5px; text-transform: uppercase; transition: color .15s; position: relative; }
        .nav-btn.active { color: #2c2520; }
        .nav-btn .lbl { font-size: 7px; margin-top: 1px; }
        .ci { flex: 1; padding: 12px 14px; background: #faf7f0; border: 1px solid #d4ccb8; border-right: none; color: #2c2520; font-family: 'JetBrains Mono', monospace; font-size: 13px; outline: none; }
        .ci:focus { border-color: #8b7355; }
        .ci::placeholder { color: #b0a48e; }
        .sb { padding: 12px 18px; background: #2c2520; border: none; color: #f0ece3; font-family: 'JetBrains Mono', monospace; font-size: 10px; letter-spacing: 1px; cursor: pointer; }
        .sb:active { background: #4a3a28; }
        .atab { padding: 8px 14px; background: transparent; border: none; border-bottom: 2px solid transparent; color: #9a8e7a; font-family: 'JetBrains Mono', monospace; font-size: 8px; font-weight: 400; letter-spacing: 2px; cursor: pointer; transition: all .15s; text-transform: uppercase; white-space: nowrap; }
        .atab.active { color: #2c2520; border-bottom-color: #8b7355; }
        .fcard { padding: 13px 14px; border-bottom: 1px solid #e8e2d4; transition: background .12s; }
        .fcard:hover { background: rgba(0,0,0,0.01); }
        .upload-btn { padding: 5px 12px; background: transparent; border: 1px solid #8b7355; color: #8b7355; font-family: 'JetBrains Mono', monospace; font-size: 8px; cursor: pointer; letter-spacing: 1px; transition: all .15s; }
        .upload-btn:hover { background: rgba(139,115,85,0.08); }
        .badge { display: inline-flex; align-items: center; justify-content: center; min-width: 16px; height: 16px; border-radius: 8px; padding: 0 4px; font-family: 'JetBrains Mono', monospace; font-size: 8px; font-weight: 500; }
      `}</style>
      <div className="bp-bg" />

      {/* HEADER */}
      <header style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0 14px", height: "48px", background: "#2c2520", borderBottom: "1px solid #1a1510", position: "relative", zIndex: 20, flexShrink: 0 }}>
        <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
          <img src="data:image/jpeg;base64," alt="Belfast" style={{ height: "32px", width: "auto", filter: "invert(1) brightness(0.85) sepia(1) saturate(3) hue-rotate(5deg)", display: "block" }} />
          <div style={{ display: "flex", alignItems: "baseline", gap: "1px" }}>
            <span style={{ fontFamily: "'Raleway', sans-serif", fontSize: "16px", fontWeight: 800, color: "#ffffff", letterSpacing: "3px" }}>BELFAST</span><span style={{ fontFamily: "'Raleway', sans-serif", fontSize: "16px", fontWeight: 300, color: "#c4a96a", letterSpacing: "2px" }}>IA</span>
          </div>
          <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "rgba(196,169,106,0.45)", letterSpacing: "1px", maxWidth: "120px", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{projectName}</span>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
          {/* Completeness indicator */}
          <div style={{ display: "flex", alignItems: "center", gap: "5px" }}>
            <div style={{ width: "32px", height: "3px", background: "rgba(255,255,255,0.1)", borderRadius: "2px", overflow: "hidden" }}>
              <div style={{ height: "100%", width: `${puntaje}%`, background: puntaje >= 80 ? "#5a7a4a" : puntaje >= 50 ? "#c4a96a" : "#9a3020", transition: "width 1s" }} />
            </div>
            <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "8px", color: puntaje >= 80 ? "#7aaa6a" : puntaje >= 50 ? "#c4a96a" : "#c46a5a" }}>{puntaje}%</span>
          </div>
          <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", padding: "2px 7px", background: isConstructor ? "rgba(138,90,58,0.25)" : "rgba(74,106,138,0.25)", border: `1px solid ${isConstructor ? "rgba(138,90,58,0.4)" : "rgba(74,106,138,0.4)"}`, color: isConstructor ? "#c48a6a" : "#8ab4d8" }}>
            {isConstructor ? "OBRA" : "ESTUDIO"}
          </span>
          <button onClick={() => setRole(null)} style={{ background: "transparent", border: "1px solid rgba(196,169,106,0.15)", color: "rgba(196,169,106,0.4)", fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", padding: "3px 7px", cursor: "pointer" }}>✕</button>
        </div>
      </header>

      {/* CONTENT */}
      <div style={{ flex: 1, overflow: "hidden", position: "relative", zIndex: 2, display: "flex", flexDirection: "column" }}>

        {/* ── CHAT ── */}
        {view === "chat" && (
          <div style={{ flex: 1, display: "flex", flexDirection: "column", overflow: "hidden" }}>

            {/* Status bar */}
            {critCount > 0 && (
              <div style={{ padding: "7px 14px", background: "rgba(160,50,30,0.07)", borderBottom: "1px solid rgba(160,50,30,0.2)", display: "flex", alignItems: "center", gap: "8px", flexShrink: 0 }}>
                <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "8px", color: "#9a3020" }}>
                  ⚠ {critCount} ítem{critCount > 1 ? "s" : ""} crítico{critCount > 1 ? "s" : ""} sin resolver
                </span>
                <button onClick={() => setView("audit")} style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "8px", color: "#9a3020", background: "transparent", border: "1px solid rgba(160,50,30,0.3)", padding: "2px 7px", cursor: "pointer" }}>Ver auditoría →</button>
              </div>
            )}

            {/* Studio upload bar */}
            {!isConstructor && (
              <div style={{ padding: "7px 14px", background: "#f5f1e8", borderBottom: "1px solid #e2ddd0", display: "flex", alignItems: "center", gap: "10px", flexShrink: 0 }}>
                <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#9a8e7a", letterSpacing: "1px" }}>PLANOS</span>
                <button className="upload-btn" onClick={() => fileRef.current?.click()}>+ Subir PDF</button>
                <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#b0a48e" }}>
                  {pdfStatus === "demo" ? "Datos de demo activos" : pdfStatus === "analyzing" ? "Analizando…" : pdfStatus === "ready" ? `✓ ${pdfName}` : pdfName}
                </span>
                <input ref={fileRef} type="file" accept=".pdf" style={{ display: "none" }} onChange={handlePdf} />
              </div>
            )}

            {/* Quick questions */}
            {isConstructor && (
              <div style={{ padding: "7px 12px", background: "#f5f1e8", borderBottom: "1px solid #e2ddd0", display: "flex", gap: "6px", overflowX: "auto", flexShrink: 0 }}>
                {QUICK_Q.map(q => <button key={q} className="qq" onClick={() => sendMessage(q)}>{q}</button>)}
              </div>
            )}

            {/* Messages */}
            <div style={{ flex: 1, overflowY: "auto", padding: "14px", display: "flex", flexDirection: "column", gap: "12px" }}>
              {messages.map((m, i) => (
                <div key={i} className="msg-in" style={{ display: "flex", flexDirection: "column", alignItems: m.role === "user" ? "flex-end" : "flex-start" }}>
                  {m.role === "ai" && <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#9a8e7a", marginBottom: "4px", letterSpacing: "2px" }}>BELFAST</div>}
                  <div style={{
                    maxWidth: "90%", padding: "11px 14px",
                    background: m.role === "user" ? (isConstructor ? "rgba(138,90,58,0.09)" : "rgba(74,106,138,0.09)") : "#faf7f0",
                    border: `1px solid ${m.role === "user" ? (isConstructor ? "rgba(138,90,58,0.22)" : "rgba(74,106,138,0.22)") : "#d8d0bc"}`,
                    fontFamily: "'Cormorant Garamond', serif", fontSize: "16px", color: "#2c2520", lineHeight: "1.65",
                  }} dangerouslySetInnerHTML={{ __html: mdRender(m.text) }} />
                </div>
              ))}
              {isTyping && (
                <div className="msg-in" style={{ display: "flex", flexDirection: "column", alignItems: "flex-start" }}>
                  <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#9a8e7a", marginBottom: "4px", letterSpacing: "2px" }}>BELFAST</div>
                  <div style={{ padding: "11px 14px", background: "#faf7f0", border: "1px solid #d8d0bc" }}>
                    <span className="tdot"/><span className="tdot"/><span className="tdot"/>
                  </div>
                </div>
              )}
              {aiError && <div style={{ padding: "9px 12px", background: "rgba(139,58,42,0.06)", border: "1px solid rgba(139,58,42,0.2)", fontFamily: "'JetBrains Mono', monospace", fontSize: "10px", color: "#8b3a2a" }}>{aiError}</div>}
              <div ref={chatEndRef} />
            </div>

            {/* Input */}
            <div style={{ padding: "10px 12px", borderTop: "1px solid #d8d0bc", background: "#faf7f0", flexShrink: 0 }}>
              <div style={{ display: "flex" }}>
                <input className="ci" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === "Enter" && !e.shiftKey && sendMessage()} placeholder={isConstructor ? "¿Cuánto hierro para la fundación?" : "Preguntá sobre el proyecto…"} />
                <button className="sb" onClick={() => sendMessage()}>Enviar</button>
              </div>
            </div>
          </div>
        )}

        {/* ── AUDITORÍA ── */}
        {view === "audit" && (
          <div style={{ flex: 1, display: "flex", flexDirection: "column", overflow: "hidden" }}>
            {/* Score header */}
            <div style={{ padding: "14px 16px", background: "#faf7f0", borderBottom: "1px solid #d8d0bc", flexShrink: 0 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: "10px" }}>
                <div>
                  <div style={{ fontFamily: "'Libre Baskerville', serif", fontSize: "17px", color: "#2c2520" }}>Auditoría del proyecto</div>
                  <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "8px", color: "#9a8e7a", marginTop: "2px" }}>{projectName}</div>
                </div>
                <div style={{ textAlign: "right" }}>
                  <div style={{ fontFamily: "'Libre Baskerville', serif", fontSize: "26px", fontWeight: 700, color: puntaje >= 80 ? "#5a7a4a" : puntaje >= 50 ? "#8a6a20" : "#9a3020", lineHeight: 1 }}>{puntaje}%</div>
                  <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "8px", color: "#9a8e7a" }}>completo</div>
                </div>
              </div>
              {/* Progress bar */}
              <div style={{ height: "4px", background: "#e2ddd0", borderRadius: "2px", overflow: "hidden", marginBottom: "10px" }}>
                <div style={{ height: "100%", width: `${puntaje}%`, background: puntaje >= 80 ? "#5a7a4a" : puntaje >= 50 ? "#c4a96a" : "#9a3020", transition: "width 1s" }} />
              </div>
              {/* Stats */}
              <div style={{ display: "flex", gap: "8px" }}>
                {[
                  { l: "Faltantes", v: faltantes.length, c: faltantes.length > 0 ? "#9a3020" : "#5a7a4a" },
                  { l: "Críticos", v: critCount, c: critCount > 0 ? "#9a3020" : "#5a7a4a" },
                  { l: "Advertencias", v: advertencias.length, c: advertencias.length > 0 ? "#8a6a20" : "#5a7a4a" },
                  { l: "Alertas enviadas", v: alerts.length, c: "#4a6a8a" },
                ].map(s => (
                  <div key={s.l} style={{ flex: 1, padding: "8px 6px", background: "#f0ece3", border: "1px solid #e2ddd0", textAlign: "center" }}>
                    <div style={{ fontFamily: "'Libre Baskerville', serif", fontSize: "18px", fontWeight: 700, color: s.c, lineHeight: 1 }}>{s.v}</div>
                    <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#9a8e7a", marginTop: "2px", letterSpacing: "0.5px" }}>{s.l}</div>
                  </div>
                ))}
              </div>
            </div>

            {/* Tabs */}
            <div style={{ display: "flex", borderBottom: "1px solid #d8d0bc", background: "#f5f1e8", flexShrink: 0, overflowX: "auto" }}>
              {[
                { id: "faltantes", label: `Faltantes (${faltantes.length})` },
                { id: "advertencias", label: `Advertencias (${advertencias.length})` },
                { id: "alertas", label: `Alertas al estudio (${alerts.length})` },
              ].map(t => (
                <button key={t.id} className={`atab ${activeAuditTab === t.id ? "active" : ""}`} onClick={() => setActiveAuditTab(t.id)}>{t.label}</button>
              ))}
            </div>

            {/* Content */}
            <div style={{ flex: 1, overflowY: "auto" }}>

              {activeAuditTab === "faltantes" && (
                <div>
                  {faltantes.length === 0 && (
                    <div style={{ padding: "40px 20px", textAlign: "center", fontFamily: "'Cormorant Garamond', serif", fontSize: "16px", color: "#9a8e7a", fontStyle: "italic" }}>
                      Documentación completa — sin faltantes
                    </div>
                  )}
                  {faltantes.map(f => {
                    const st = IMPACTO_STYLE[f.impacto] || IMPACTO_STYLE["menor"];
                    return (
                      <div key={f.id} className="fcard" style={{ borderLeft: `3px solid ${st.border}` }}>
                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: "6px", gap: "8px" }}>
                          <div style={{ display: "flex", gap: "6px", alignItems: "center", flexWrap: "wrap" }}>
                            <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", padding: "2px 6px", background: st.bg, border: `1px solid ${st.border}`, color: st.color, letterSpacing: "1px" }}>{st.label.toUpperCase()}</span>
                            <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#9a8e7a", letterSpacing: "1px" }}>{f.sector} · {f.categoria}</span>
                            {f.bloquea_computo && <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", padding: "2px 6px", background: "rgba(160,50,30,0.06)", border: "1px solid rgba(160,50,30,0.2)", color: "#9a3020" }}>BLOQUEA CÓMPUTO</span>}
                          </div>
                          <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "8px", color: "#b0a48e", flexShrink: 0 }}>{f.id}</span>
                        </div>
                        <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "15px", color: "#2c2520", marginBottom: "6px", lineHeight: 1.4 }}>{f.descripcion}</div>
                        <div style={{ padding: "8px 10px", background: "#f5f1e8", border: "1px solid #e8e2d4" }}>
                          <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#8b7355", letterSpacing: "1px", marginBottom: "3px" }}>SE NECESITA:</div>
                          <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "9px", color: "#6a5a48", lineHeight: 1.5 }}>{f.datos_necesarios}</div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}

              {activeAuditTab === "advertencias" && (
                <div>
                  {advertencias.length === 0 && (
                    <div style={{ padding: "40px 20px", textAlign: "center", fontFamily: "'Cormorant Garamond', serif", fontSize: "16px", color: "#9a8e7a", fontStyle: "italic" }}>Sin advertencias</div>
                  )}
                  {advertencias.map(a => (
                    <div key={a.id} className="fcard" style={{ borderLeft: "3px solid rgba(160,120,30,0.4)" }}>
                      <div style={{ display: "flex", gap: "6px", marginBottom: "6px", alignItems: "center" }}>
                        <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", padding: "2px 6px", background: "rgba(160,120,30,0.08)", border: "1px solid rgba(160,120,30,0.3)", color: "#8a6a20", letterSpacing: "1px" }}>
                          {a.tipo === "inconsistencia" ? "INCONSISTENCIA" : a.tipo === "dato_estimado" ? "DATO ESTIMADO" : "ESP. INCOMPLETA"}
                        </span>
                        <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#9a8e7a" }}>{a.sector}</span>
                        <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "8px", color: "#b0a48e", marginLeft: "auto" }}>{a.id}</span>
                      </div>
                      <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "15px", color: "#2c2520", lineHeight: 1.45 }}>{a.descripcion}</div>
                    </div>
                  ))}
                </div>
              )}

              {activeAuditTab === "alertas" && (
                <div>
                  {alerts.length === 0 && (
                    <div style={{ padding: "32px 20px", textAlign: "center" }}>
                      <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "16px", color: "#9a8e7a", fontStyle: "italic", marginBottom: "8px" }}>Sin alertas enviadas al estudio</div>
                      <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "8px", color: "#b0a48e", lineHeight: 1.6 }}>
                        Cuando la constructora consulte algo que falta,<br/>se genera una alerta automática acá.
                      </div>
                    </div>
                  )}
                  {alerts.map(a => (
                    <div key={a.id} className="fcard" style={{ borderLeft: "3px solid rgba(74,106,138,0.4)" }}>
                      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "5px" }}>
                        <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", padding: "2px 6px", background: "rgba(74,106,138,0.08)", border: "1px solid rgba(74,106,138,0.25)", color: "#4a6a8a", letterSpacing: "1px" }}>ALERTA AL ESTUDIO</span>
                        <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "8px", color: "#b0a48e" }}>{a.date} {a.time}</span>
                      </div>
                      <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "8px", color: "#9a8e7a", marginBottom: "4px" }}>Consulta de la constructora:</div>
                      <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "15px", color: "#2c2520", fontStyle: "italic" }}>"{a.query}"</div>
                      <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "8px", color: "#8a6a20", marginTop: "6px" }}>→ Información no disponible en el proyecto — requiere completar documentación</div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

        {/* ── CÓMPUTO ── */}
        {view === "computo" && (
          <div style={{ flex: 1, overflowY: "auto" }}>
            {/* Summary */}
            <div style={{ padding: "12px", display: "grid", gridTemplateColumns: "1fr 1fr", gap: "8px" }}>
              {(computo.resumen_general || []).map((r, i) => (
                <div key={i} style={{ padding: "11px", background: "#faf7f0", border: "1px solid #d8d0bc" }}>
                  <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", color: "#9a8e7a", letterSpacing: "1px", textTransform: "uppercase", marginBottom: "3px" }}>{r.material}</div>
                  <div style={{ fontFamily: "'Libre Baskerville', serif", fontSize: "19px", fontWeight: 700, color: "#2c2520", lineHeight: 1 }}>{fmt(r.cantidad_total)}</div>
                  <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "9px", color: accentColor, marginTop: "2px" }}>{r.unidad}</div>
                </div>
              ))}
            </div>

            {/* By sector */}
            {(computo.sectores || []).map(sector => (
              <div key={sector.nombre}>
                <div style={{ padding: "9px 14px", background: "#f0ece3", borderTop: "1px solid #d8d0bc", borderBottom: "1px solid #d8d0bc", display: "flex", justifyContent: "space-between" }}>
                  <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "9px", color: "#8b7355", letterSpacing: "2px", textTransform: "uppercase" }}>{sector.nombre}</span>
                  {sector.superficie_m2 > 0 && <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "8px", color: "#b0a48e" }}>{sector.superficie_m2} m²</span>}
                </div>
                {(sector.items || []).map((item, j) => (
                  <div key={j} style={{ display: "flex", padding: "10px 14px", borderBottom: "1px solid #ede8dc", gap: "10px", alignItems: "flex-start" }}>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "15px", color: "#2c2520" }}>{item.material}</div>
                      <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "8px", color: "#9a8e7a", marginTop: "2px" }}>{item.detalle}</div>
                      <div style={{ display: "flex", gap: "5px", marginTop: "4px" }}>
                        <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", padding: "1px 6px", background: "rgba(139,115,85,0.08)", border: "1px solid rgba(139,115,85,0.2)", color: "#8b7355" }}>{item.categoria}</span>
                        {item.confianza && item.confianza !== "alta" && (
                          <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "7px", padding: "1px 6px", background: "rgba(160,120,30,0.08)", border: "1px solid rgba(160,120,30,0.25)", color: "#8a6a20" }}>
                            {item.confianza === "media" ? "estimado" : "dato aprox."}
                          </span>
                        )}
                      </div>
                    </div>
                    <div style={{ textAlign: "right", flexShrink: 0 }}>
                      <div style={{ fontFamily: "'Libre Baskerville', serif", fontSize: "18px", fontWeight: 700, color: accentColor }}>{fmt(item.cantidad)}</div>
                      <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: "9px", color: "#9a8e7a" }}>{item.unidad}</div>
                    </div>
                  </div>
                ))}
              </div>
            ))}
            <div style={{ height: "16px" }} />
          </div>
        )}
      </div>

      {/* BOTTOM NAV */}
      <nav style={{ display: "flex", height: "54px", background: "#faf7f0", borderTop: "1px solid #d8d0bc", position: "relative", zIndex: 20, flexShrink: 0 }}>
        <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: "2px", background: `linear-gradient(90deg, #d8d0bc, ${accentColor}70, #d8d0bc)` }} />

        <button className={`nav-btn ${view === "chat" ? "active" : ""}`} onClick={() => setView("chat")}>
          <svg width="18" height="18" viewBox="0 0 20 20" fill="none"><rect x="2" y="3" width="16" height="11" rx="1" fill="none" stroke="currentColor" strokeWidth="1.2"/><line x1="2" y1="14" x2="5" y2="17" stroke="currentColor" strokeWidth="1.2"/><line x1="6" y1="8" x2="14" y2="8" stroke="currentColor" strokeWidth="0.8"/><line x1="6" y1="11" x2="11" y2="11" stroke="currentColor" strokeWidth="0.8"/></svg>
          <span className="lbl">Consultar</span>
        </button>

        <button className={`nav-btn ${view === "audit" ? "active" : ""}`} onClick={() => setView("audit")} style={{ position: "relative" }}>
          {(critCount + unreadAlerts) > 0 && (
            <span className="badge" style={{ position: "absolute", top: "4px", right: "calc(50% - 18px)", background: "#9a3020", color: "#fff", fontSize: "7px" }}>
              {critCount + unreadAlerts}
            </span>
          )}
          <svg width="18" height="18" viewBox="0 0 20 20" fill="none"><path d="M10 3 L18 17 L2 17 Z" fill="none" stroke="currentColor" strokeWidth="1.2"/><line x1="10" y1="9" x2="10" y2="13" stroke="currentColor" strokeWidth="1.2"/><circle cx="10" cy="15" r="0.8" fill="currentColor"/></svg>
          <span className="lbl">Auditoría</span>
        </button>

        <button className={`nav-btn ${view === "computo" ? "active" : ""}`} onClick={() => setView("computo")}>
          <svg width="18" height="18" viewBox="0 0 20 20" fill="none"><rect x="3" y="2" width="14" height="16" fill="none" stroke="currentColor" strokeWidth="1.2"/><line x1="6" y1="7" x2="14" y2="7" stroke="currentColor" strokeWidth="0.8"/><line x1="6" y1="10" x2="14" y2="10" stroke="currentColor" strokeWidth="0.8"/><line x1="6" y1="13" x2="10" y2="13" stroke="currentColor" strokeWidth="0.8"/></svg>
          <span className="lbl">Cómputo</span>
        </button>

        {!isConstructor && (
          <button className="nav-btn" onClick={() => fileRef.current?.click()}>
            <svg width="18" height="18" viewBox="0 0 20 20" fill="none"><rect x="4" y="3" width="12" height="14" fill="none" stroke="currentColor" strokeWidth="1.2"/><line x1="10" y1="7" x2="10" y2="13" stroke="currentColor" strokeWidth="1.2"/><line x1="7" y1="10" x2="10" y2="7" stroke="currentColor" strokeWidth="1.2"/><line x1="13" y1="10" x2="10" y2="7" stroke="currentColor" strokeWidth="1.2"/></svg>
            <span className="lbl">Subir plano</span>
            <input ref={fileRef} type="file" accept=".pdf" style={{ display: "none" }} onChange={handlePdf} />
          </button>
        )}
      </nav>
    </div>
  );
}
